import axios from "axios";
import "./App.css";
import "./ToDoList.css";
import React, { useState, useEffect, useCallback } from "react";

function ToDoList() {
  const [tasks, setTasks] = useState([]);
  const [filteredTasks, setFilteredTasks] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(0);

  const pageSize = 50;

  const loadMoreTasks = useCallback(async (currentPage) => {
    if (isLoading || !hasMore) return;

    setIsLoading(true);
    try {
      const response = await axios.get(
        `https://releasetrain.io/api/c/names?start=${
          currentPage * pageSize
        }&limit=${pageSize}`
      );

      if (response.data.length === 0) {
        setHasMore(false);
      } else {
        setTasks((prevTasks) => {
          const newTasks = response.data.map((item) => ({
            text: item,
            id: item,
          }));

          // Ensure no duplicates using Map
          const uniqueTasks = [
            ...new Map(
              [...prevTasks, ...newTasks].map((task) => [task.id, task])
            ).values(),
          ];

          return uniqueTasks;
        });

        setPage((prevPage) => prevPage + 1);
      }
    } catch (error) {
      console.error("Error loading more tasks:", error);
    }
    setIsLoading(false);
  }, [isLoading, hasMore, pageSize]);

  // Load tasks on initial render
  useEffect(() => {
    loadMoreTasks(0);
  }, [loadMoreTasks]);

  // Filter tasks based on search term
  useEffect(() => {
    if (searchTerm) {
      const filtered = tasks.filter((task) =>
        task.text.toLowerCase().includes(searchTerm.toLowerCase())
      );
      setFilteredTasks(filtered);
    } else {
      setFilteredTasks(tasks);
    }
  }, [searchTerm, tasks]);

  // Handle search input change
  const handleSearchChange = (e) => setSearchTerm(e.target.value);

  return (
    <div className="to-do-list">
      <h1>To-Do List</h1>

      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search tasks..."
        value={searchTerm}
        onChange={handleSearchChange}
        className="search-bar"
      />

      {/* Task List */}
      <div className="task-list">
        {filteredTasks.map((task) => (
          <div key={task.id} className="task-item">
            <span>{task.text}</span>
          </div>
        ))}
      </div>

      {isLoading && <p className="loading-text">Loading more tasks...</p>}
    </div>
  );
}

export default ToDoList;
